import React, { useState } from "react";
import images from "../images"; // Asegúrate de tener las imágenes importadas aquí
import { useTranslation } from "gatsby-plugin-react-i18next";

interface ImageItem {
  src: string;
  alt: string;
  description: string;
}

const Gallery: React.FC = () => {
  const { t } = useTranslation();
  const [selectedImage, setSelectedImage] = useState<ImageItem | null>(null);

  const galleryImages: ImageItem[] = [
    { src: images.gallery_1.src ?? "", alt: images.gallery_1.alt ?? "", description: t("gallery.desc_1") },
    { src: images.gallery_3.src ?? "", alt: images.gallery_3.alt ?? "", description: t("gallery.desc_3") },
    { src: images.gallery_2.src ?? "", alt: images.gallery_2.alt ?? "", description: t("gallery.desc_2") },
    { src: images.gallery_4.src ?? "", alt: images.gallery_4.alt ?? "", description: t("gallery.desc_4") },
  ];

  return (
    <>
      <div className="max-w-4xl mx-auto px-4">
        <h2 className="text-secondary tangerine-bold text-8xl text-center">
          {t("gallery.title")}
        </h2>
        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 mt-8">
          {galleryImages.map((image, index) => (
            <div key={index} className="cursor-pointer" onClick={() => setSelectedImage(image)}>
              <img className="h-48 aspect-auto rounded-lg shadow-lg" src={image.src} alt={image.alt} />
            </div>
          ))}
        </div>
      </div>

      {selectedImage && (
        <div className="fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center z-50">
          <div className="bg-white p-6 rounded-lg shadow-lg max-w-lg text-center relative">
            <button
              className="absolute top-2 right-2 text-gray-600 hover:text-gray-900 text-2xl"
              onClick={() => setSelectedImage(null)}
            >
              &times;
            </button>
            <img className="w-full rounded-lg mb-4" src={selectedImage.src} alt={selectedImage.alt} />
            <p className="text-lg text-gray-700">{selectedImage.description}</p>
          </div>
        </div>
      )}
    </>
  );
};

export default Gallery;
