import React, { useContext, useState } from "react";
import { CartContext } from "../context/cartContext";
import data from "../data/data.json";
import { Link } from "gatsby";
import { useTranslation } from "gatsby-plugin-react-i18next";
import images from "../images";
import { Product } from "../interfaces";
import { UserProfile } from "../interfaces";
import { PiShoppingCartDuotone } from "react-icons/pi";
import { FiArrowRight } from "react-icons/fi";

const userData: UserProfile = data;

const ProductPage = () => {
  const { t } = useTranslation();
  const cartContext = useContext(CartContext);
  const [selectedProduct, setSelectedProduct] = useState<Product | null>(null);

  if (!cartContext) {
    return <div>{t("cart.cartContextError")}</div>;
  }

  const { addToCart, cart } = cartContext;
  const products = data.products;
  const totalItems = cart.reduce((sum, item) => sum + item.quantity, 0);

  return (
    <div className="container mx-auto p-4">
      
      {/* Encabezado con botón de acceso al carrito */}
      <div className="flex justify-between items-center mb-4">
        <h1 className="text-2xl font-bold">{t("cart.products")}</h1>
        <Link to="/cart" className="bg-secondary text-white relative items-center px-4 py-2 rounded flex gap-4 text-2xl">
        <PiShoppingCartDuotone className="text-primary text-2xl" />
        {t("cart.cart")} ({totalItems}) <FiArrowRight className="text-2xl mr-4" />
        </Link>
      </div>

      {/* Grid de productos con overlay */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {products.map((product) => (
          <div
            key={product.id}
            className="relative cursor-pointer overflow-hidden rounded-lg"
            onClick={() => setSelectedProduct({ ...product, quantity: 1 })}
          >
            <img
              src={`${images[product.image].src}`}
              alt={`${images[product.image].alt}`}
              className="w-full h-64 object-cover"
            />
            <div className="bg-black text-light absolute inset-0 bg-opacity-20 flex flex-col justify-end p-4">
              <h2 className="text-6xl charm-regular text-shadow overflow-y-auto">{product.name}</h2>
              <p className="text-primary text-shadow">${product.price}</p>
            </div>
          </div>
        ))}
      </div>

      {/* Modal de detalles del producto */}
      {selectedProduct && (
        <div className="bg-black bg-opacity-75 fixed z-[60] inset-0 flex items-center justify-center p-4 sm:p-0">
          <div className="bg-terciary p-4 rounded-lg shadow-lg max-w-4xl w-full relative h-full sm:h-auto overflow-y-auto">
            { totalItems > 0 && <span className=" bg-secondary text-light text-xl px-4 rounded py-2">{t("cart.productInCart")}: <span className="text-2xl text-shadow">{totalItems}</span></span>}
            <button
              className="text-light absolute top-4 right-4 text-3xl hover:text-secondary"
              onClick={() => setSelectedProduct(null)}
            >
              ✖
            </button>

            <section className={styles.containerImages}>
              {selectedProduct.image && images[selectedProduct.image] && (<img
                src={`${images[selectedProduct.image].src}`}
                alt={`${images[selectedProduct.image].alt}`}
                className={styles.images}
              />)}
              {selectedProduct.image2 && images[selectedProduct.image2] && (<img
                src={`${images[selectedProduct.image2].src}`}
                alt={`${images[selectedProduct.image2].alt}`}
                className={styles.images}
              />)}
              {selectedProduct.image3 && images[selectedProduct.image3] && (<img
                src={`${images[selectedProduct.image3].src}`}
                alt={`${images[selectedProduct.image3].alt}`}
                className={styles.images}
              />)}
            </section>

            <h2 className="text-secondary text-7xl text-center font-semibold charm-regular text-shadow mt-4">{selectedProduct.name}</h2>
            <p className=" text-pink text-shadow text-3xl text-center my-2">${selectedProduct.price}</p>
            <button
              className="bg-secondary text-semilight text-shadow text-2xl mt-4 px-4 py-2 rounded w-full"
              onClick={() => {
                addToCart({ ...selectedProduct, quantity: 1 });
              }}
            >
              {t("cart.addToCart")}
            </button>
            <p className="text-pink 
            text-xl mt-4">{t("notes.reservation")}</p>
            <p className="text-pink 
            text-xl mt-4">{t("notes.conservation")}</p>
            <p className="text-pink 
            text-xl mt-4">{t("notes.deliveryPlace")}</p>
          </div>
        </div>
      )}
    </div>
  );
};

export default ProductPage;

const styles = {
  container: "container mx-auto p-4",
  containerImages: "flex gap-4 justify-evenly items-center py-6 flex-col sm:flex-row",
  images: "w-full h-64 w-64 object-cover rounded shadow-2xl",
}
