import * as React from "react";
import { graphql, type PageProps } from "gatsby";
import Layout from "../components/layout";
import { UserProfile } from "../interfaces";
import data from "../data/data.json";
import Products from "../components/products";
import Carousel from "../components/carousel";
import images from "../images";
import { useTranslation } from "gatsby-plugin-react-i18next";
import { FaCheck } from "react-icons/fa";
import Gallery from "../components/gallery";

const IndexPage: React.FC<PageProps> = () => {
  const userData: UserProfile = data;
  const { t } = useTranslation();
  const ingredientsContent = t("ingredients.content", { returnObjects: true }) || [];
  const aboutmeContent = t("aboutMe.content", { returnObjects: true }) || [];
  const carouselImages = [
    { src: images.bouquet.src, alt: images.bouquet.alt },
    { src: images.chocolate_roses.src, alt: images.chocolate_roses.alt },
    { src: images.gift_box_full.src, alt: images.gift_box_full.alt },
    { src: images.inside_flowers.src, alt: images.inside_flowers.alt },
  ];

  const textOverlay = [
    { content: t("carousel.text_1") },
    { content: t("carousel.text_2") },
    { content: t("carousel.text_3") },
    { content: t("carousel.text_4") },
  ];

  return (
    <Layout data={userData}>
      <section className="bg-primary py-16 mt-8 relative">
        <div className="max-w-7xl mx-auto px-4 grid grid-cols-1 md:grid-cols-2 gap-8">
          {/* Contenedor del Carousel */}
          <div className="w-full">
            <Carousel
              images={carouselImages}
              textOverlay={textOverlay}
              speed={6000}
            />
          </div>

          {/* Contenedor del texto */}
          <div className="w-full max-w-4xl mx-auto px-6">
            <h1 className="text-secondary tangerine-regular text-6xl md:text-8xl font-bold text-center">
              {t("home.slogan")}
            </h1>
            {(t("home.content", { returnObjects: true }) as any[]).map(
              (item, index) => (
                <p
                  key={index}
                  className="text-pink text-xl text-center mt-4"
                >
                  {item.copy}
                </p>
              )
            )}
          </div>
        </div>
      </section>
      <section id={`${userData.menu[0]}1`}>
        <Products />
      </section>
      <section className="bg-terciary flex flex-col py-8 mt-8 relative" id={userData.menu[1]}>

        <div className="relative z-50">
          <h2 className="tangerine-bold text-8xl text-center text-secondary">
            {t("ingredients.title")}
          </h2>
          <div className="max-w-4xl mx-auto p-8 text-pink">
            <ul className="flex flex-col gap-4">
            {Array.isArray(ingredientsContent) &&
                ingredientsContent.map(
                (item, index) => (
                  <li key={index} className="text-xl flex flex-row gap-4">
                    <span className="self-center">
                      <FaCheck className="text-secondary w-6 h-6 mr-4" />
                    </span>
                    {item.copy}
                  </li>
                )
              )}
            </ul>
          </div>
        </div>
      </section>
      <section className="bg-light py-16 mt-8 relative" id={userData.menu[2]}>
        <div className="max-w-7xl mx-auto px-4 grid grid-cols-1 md:grid-cols-2 gap-8">
          <div className="bg-terciary ">
            <img
              className="w-full mx-auto"
              src={images.gift_box.src}
              alt={images.gift_box.alt}
            />
          </div>
          <div className="self-center flex flex-col gap-4">
            <h2 className="text-secondary tangerine-bold text-8xl text-center">
              {t("gifts.title")}
            </h2>
            <p className="text-pink max-w-4xl mx-auto p-8 text-xl ">
              {t("gifts.copy")}
            </p>
          </div>
        </div>
      </section>
      <section className="bg-semilight py-16 mt-8 relative" id={userData.menu[3]}>
        <div className="max-w-7xl mx-auto px-4 grid grid-cols-1 md:grid-cols-2 gap-8">
          <div className="self-center flex flex-col gap-4">
            <div className="max-w-2xl mx-auto p-8 text-light">
            {Array.isArray(aboutmeContent) &&
                aboutmeContent.map(
                (item, index) => (
                  <p key={index} className="text-xl flex flex-row gap-4">
                    {item.copy}
                  </p>
                )
              )}
              <p className="text-secondary text-shadow tangerine-bold text-7xl flex mt-4 justify-end ">Kahina</p>
          </div>
          </div>
          <div className="flex items-center">
            <img
              className="w-full mx-auto"
              src={images.who_i_am.src}
              alt={images.who_i_am.alt}
            />
          </div>          
        </div>
      </section>
      <section className="bg-light flex flex-col  py-8 mt-8 relative">
        <div className="relative z-50">
          <h2 className="text-secondary tangerine-bold text-8xl text-center">
            {t("notes.title")}
          </h2>
          <ul className="text-pink max-w-4xl mx-auto p-8 text-xl ">
            <li className="flex my-4">
              <span className="self-center">
                <FaCheck className="text-secondary w-6 h-6 mr-4" />
              </span>
              {t("notes.reservation")}
            </li>
            <li className="flex my-4">
              <span className="self-center">
                <FaCheck className="text-secondary w-6 h-6 mr-4" />
              </span>
              {t("notes.conservation")}
            </li>
            <li className="flex my-4">
              <span className="self-center">
                <FaCheck className="text-secondary w-6 h-6 mr-4" />
              </span>
              {t("notes.deliveryPlace")}
            </li>
          </ul>
        </div>
      </section>
      <section className="bg-semilight py-16 mt-8 relative" id={userData.menu[4]}>
        <Gallery />
      </section>

    </Layout>
  );
};

export default IndexPage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;
